mapper.select:
SELECT * FROM ( SELECT 'department' AS type, so.ID AS id, so.`NAME` AS `name`, so.TENANT_ID AS tenantId, so.PARENT_ID AS parentId, so.CATEGORY AS category, so.SORT_CODE AS sortCode, '' as avatar FROM SYS_ORG so WHERE so.DELETE_FLAG = 'NOT_DELETE'
AND so.PARENT_ID = #{id}
AND so.NAME LIKE CONCAT('%', #{searchKey}, '%')
UNION ALL
SELECT 'user' AS type, su.ID AS id, su.`NAME` AS `name`, su.TENANT_ID AS tenantId, su.ORG_ID AS parentId, "USER" AS category, su.SORT_CODE AS sortCode, su.AVATAR as avatar FROM SYS_USER su WHERE su.USER_STATUS = 'ENABLE' AND su.DELETE_FLAG = 'NOT_DELETE'
AND su.ORG_ID = #{id}
AND su.NAME LIKE CONCAT('%', #{searchKey}, '%')
) temp ORDER BY CASE WHEN temp.type = 'department' THEN 1 ELSE 2 END, temp.sortCode
